<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$per=20;$p=[];$where='';if($q!==''){$where=' WHERE g.code LIKE :q OR g.libelle LIKE :q';$p['q']='%'.$q.'%';}$s=$db->prepare('SELECT COUNT(*) FROM garanties g'.$where);$s->execute($p);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$s=$db->prepare('SELECT g.*,(SELECT COUNT(*) FROM produits_garanties pg WHERE pg.garantie_id=g.id) nb FROM garanties g'.$where.' ORDER BY g.libelle LIMIT :lim OFFSET :off');foreach($p as $k=>$v)$s->bindValue(':'.$k,$v);$s->bindValue(':lim',$per,PDO::PARAM_INT);$s->bindValue(':off',($page-1)*$per,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();$title='Garanties';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Référentiel des garanties</h1><p class="text-secondary"><?= $total ?> garantie(s)</p></div><a class="btn btn-primary" href="form.php">+ Nouvelle garantie</a></div><form class="filter-bar" method="get"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Code ou libellé"><button class="btn btn-dark">Rechercher</button></form><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Code</th><th>Garantie</th><th>Description</th><th>Produits</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="fw-semibold"><?= e($r['code']) ?></td><td><?= e($r['libelle']) ?></td><td><?= e($r['description']) ?></td><td><?= (int)$r['nb'] ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="form.php?id=<?= (int)$r['id'] ?>">Modifier</a> <form class="d-inline" method="post" action="delete.php" data-confirm="Supprimer cette garantie ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Supprimer</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty-state">Aucune garantie trouvée.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
